import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


class _Gather(torch.autograd.Function):
    """Gather from all ranks and concatenate along a dimension.
    Backward: split the gradient, return the local rank's portion."""
    @staticmethod
    def forward(ctx, input, dim):
        ctx.dim = dim
        world_size = _world_size()
        if world_size == 1:
            return input
        input = input.contiguous()
        output = [torch.empty_like(input) for _ in range(world_size)]
        dist.all_gather(output, input)
        output[dim] = input
        return torch.cat(output, dim=dim)

    @staticmethod
    def backward(ctx, grad_output):
        world_size = _world_size()
        if world_size == 1:
            return grad_output, None
        dim = ctx.dim
        rank = _rank()
        chunk_size = grad_output.size(dim) // world_size
        return grad_output.narrow(dim, rank * chunk_size, chunk_size).contiguous(), None


class _Reduce(torch.autograd.Function):
    """All-reduce (sum) across all ranks.
    Backward: gradient passes through unchanged."""
    @staticmethod
    def forward(ctx, input):
        world_size = _world_size()
        if world_size == 1:
            return input
        output = input.contiguous().clone()
        dist.all_reduce(output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(nn.Module):
    """Linear layer with column parallelism.
    Weight is split along the output dimension (dim 0 of the weight matrix).
    Each rank computes a portion of the output, which is then gathered.
    Bias is split in the same way as the output dimension."""
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size = _world_size()
        rank = _rank()

        # Weight: (out_features, in_features) -> split along dim 0
        out_per_rank = out_features // world_size
        self.weight = nn.Parameter(
            master_weight[rank * out_per_rank:(rank + 1) * out_per_rank, :].detach().clone()
        )

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_per_rank))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        # input: (*, in_features)
        # local output: (*, out_features / world_size)
        output = F.linear(input, self.weight, self.bias)
        # Gather along the last dimension
        output = _Gather.apply(output, -1)
        return output


class RowParallelLinear(nn.Module):
    """Linear layer with row parallelism.
    Weight is split along the input dimension (dim 1 of the weight matrix).
    Each rank receives a pre-scattered slice of the input.
    Partial outputs are summed (all-reduced) across all ranks.
    Bias remains full on each rank and is added after the reduction."""
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size = _world_size()
        rank = _rank()

        # Weight: (out_features, in_features) -> split along dim 1
        in_per_rank = in_features // world_size
        self.weight = nn.Parameter(
            master_weight[:, rank * in_per_rank:(rank + 1) * in_per_rank].detach().clone()
        )

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_features))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        # input: (*, in_features / world_size) - already scattered
        # local output: (*, out_features) - partial
        output = F.linear(input, self.weight, None)
        # All-reduce (sum) across all ranks
        output = _Reduce.apply(output)
        # Add bias after reduction (to avoid adding it multiple times)
        if self.bias is not None:
            output = output + self.bias
        return output
